@Repository
public interface UserRepository extends JpaRepository<User, Long> {

    @Query("SELECT u FROM User u WHERE u.status = :status")
    @QueryHints(@QueryHint(name = "org.hibernate.fetchSize", value = "50"))
    Stream<User> streamAllByStatus(@Param("status") UserStatus status);
}

@Service
public class UserProcessingService {
    @Autowired
    private UserRepository userRepository;

    @Transactional(readOnly = true)
    public Optional<User> findFirstActiveUserWithEmail() {
        try (Stream<User> userStream = userRepository.streamAllByStatus(UserStatus.ACTIVE)) {
            return userStream
                .filter(u -> u.getEmail() != null) // Intermediate operation (lazy)
                .peek(u -> Hibernate.initialize(u.getRoles())) // Intermediate operation
                .findFirst(); // Short-circuiting terminal operation
        }
    }
}
